/* Vorab (vor kp.js): Logo von Grundriss in Lebensgröße als Rückwand-Motiv bereitlegen – nur, wenn kein eigenes Motiv gespeichert ist */
(function(){try{if(/[?&](film|vorhang)=1/.test(location.search))localStorage.setItem('kp-film',String(Date.now()))}catch(e){}})();
(function(){try{var k='kp-motiv',m=localStorage.getItem(k);if(!m){localStorage.setItem(k,"data:image/jpeg;base64,")}}catch(e){}})();
